@font-face{font-family:"Barlow";src:url(data:font/woff;base64,) format("woff");font-weight:600;font-display:swap;}
@font-face{font-family:"Barlow";src:url(data:font/woff;base64,) format("woff");font-weight:700;font-display:swap;}
