/* ===== Tokens: taken from amrabdelgawad.site/app ===== */
:root {
  --bg: #F1EBE0; --panel: #FBF8F2; --sunk: #EFE7D9;
  --border: #D8CDB9; --border2: #C4B699;
  --text: #0B0B0B; --light: #3F3A33; --muted: #5E584F;
  --accent: #8A6A35; --accent2: #6E5228;
  --green: #2E7D57; --gold: #9A6A12; --mag: #C2187A;
  --ink: #0B0B0B; --on-ink: #F1EBE0;
  --green-t: rgba(46,125,87,.08); --gold-t: rgba(154,106,18,.09); --mag-t: rgba(194,24,122,.06);
  --serif: "Bodoni Moda", Didot, "Bodoni 72", Georgia, serif;
  --sans: "Barlow", "Helvetica Neue", Arial, sans-serif;
  --ar-head: "Amiri", "IBM Plex Sans Arabic", serif;
  --ar-body: "IBM Plex Sans Arabic", "Barlow", sans-serif;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #0B0B0B; --panel: #131211; --sunk: #0F0E0D;
    --border: #2C2824; --border2: #3A332A;
    --text: #F1EBE0; --light: #CFC7BA; --muted: #A39B8E;
    --accent: #C9A96E; --accent2: #E0C48E;
    --green: #7FC8A0; --gold: #E3B45A; --mag: #E46BB0;
    --ink: #1C1A18; --on-ink: #F1EBE0;
    --green-t: rgba(127,200,160,.08); --gold-t: rgba(227,180,90,.08); --mag-t: rgba(228,107,176,.07);
    color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --bg: #0B0B0B; --panel: #131211; --sunk: #0F0E0D;
  --border: #2C2824; --border2: #3A332A;
  --text: #F1EBE0; --light: #CFC7BA; --muted: #A39B8E;
  --accent: #C9A96E; --accent2: #E0C48E;
  --green: #7FC8A0; --gold: #E3B45A; --mag: #E46BB0;
  --ink: #1C1A18; --on-ink: #F1EBE0;
  --green-t: rgba(127,200,160,.08); --gold-t: rgba(227,180,90,.08); --mag-t: rgba(228,107,176,.07);
  color-scheme: dark;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0; background: var(--bg); color: var(--text);
  font-family: var(--sans); font-size: 16px; line-height: 1.65;
  -webkit-print-color-adjust: exact; print-color-adjust: exact;
}
html[dir="rtl"] body { font-family: var(--ar-body); font-size: 16.5px; line-height: 1.85; }

/* ===== App bar (HTML only) ===== */
.appbar {
  position: sticky; top: 0; z-index: 20; height: 52px;
  background: #0B0B0B; color: #F1EBE0; border-bottom: 1px solid #8A6A35;
  display: flex; align-items: center; gap: 12px; padding: 0 16px; overflow: hidden;
}
.appbar .topo { position: absolute; inset: 0 0 0 auto; width: 320px; opacity: .55; pointer-events: none; }
html[dir="rtl"] .appbar .topo { inset: 0 auto 0 0; transform: scaleX(-1); }
.appbar .crumb { font-family: var(--serif); font-weight: 700; font-size: 18px; letter-spacing: .04em; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; position: relative; }
html[dir="rtl"] .appbar .crumb { font-family: var(--ar-head); letter-spacing: 0; }
.appbar .spacer { flex: 1; }
.appbar button {
  position: relative; background: transparent; border: 1px solid #3A332A; color: #F1EBE0;
  width: 34px; height: 34px; display: grid; place-items: center; cursor: pointer; flex: none;
}
.appbar button:hover { border-color: #C9A96E; }
.appbar svg.icon { width: 16px; height: 16px; }

main { max-width: 820px; margin: 0 auto; padding: 0 16px 72px; }

/* ===== Type ===== */
h1, h2, h3, h4, h5 { font-family: var(--serif); color: var(--text); line-height: 1.2; font-weight: 700; }
html[dir="rtl"] :is(h1, h2, h3, h4, h5) { font-family: var(--ar-head); line-height: 1.5; }
p { margin: 0 0 12px; }
ul, ol { margin: 0 0 14px; padding-inline-start: 22px; }
li { margin-bottom: 5px; }
strong { font-weight: 600; }
a { color: var(--accent); }
.eyebrow {
  font-family: var(--sans); font-size: 11px; font-weight: 600; letter-spacing: .16em;
  text-transform: uppercase; color: var(--muted); margin: 0 0 6px;
}
html[dir="rtl"] .eyebrow { font-family: var(--ar-body); letter-spacing: 0; font-size: 13px; }
.eyebrow.gold { color: var(--accent); }
.eyebrow.mag { color: var(--mag); }
.lede { color: var(--muted); font-size: 15px; max-width: 620px; }
.small { font-size: 13.5px; color: var(--muted); }

/* Part opener */
.part-open { margin: 64px 0 18px; }
.part-open h2 { font-size: 40px; margin: 0 0 8px; letter-spacing: -.01em; }
.part-open .thumb { display: block; width: 100%; aspect-ratio: 16 / 9; border: 1px solid var(--border); margin: 0 0 22px; background: #0B0B0B; }
.part-open .lede { margin-bottom: 0; }

/* Lesson heading */
h3.lesson { font-size: 30px; margin: 56px 0 14px; padding-bottom: 12px; border-bottom: 1px solid var(--border2); }
h3.lesson .num { display: block; font-family: var(--sans); font-size: 11px; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; color: var(--mag); margin-bottom: 6px; }
html[dir="rtl"] h3.lesson .num { font-family: var(--ar-body); letter-spacing: 0; font-size: 13px; }
h4 { font-size: 21px; margin: 34px 0 10px; }
h4 .sec { font-family: var(--sans); font-size: 13px; font-weight: 600; color: var(--accent); margin-inline-end: 10px; letter-spacing: .04em; }
html[dir="rtl"] h4 .sec { font-family: var(--ar-body); }
h5 { font-size: 17px; margin: 22px 0 8px; }
.case h5, .rp h5 { font-family: var(--sans); font-size: 12px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: var(--accent); margin: 14px 0 4px; }
html[dir="rtl"] :is(.case, .rp) h5 { font-family: var(--ar-body); letter-spacing: 0; font-size: 13.5px; }

/* ===== Cover ===== */
.cover { position: relative; overflow: hidden; background: #0B0B0B; color: #F1EBE0; margin: 0 0 32px; padding: 48px 20px 40px; }
.cover .topo { position: absolute; inset: 0; width: 100%; height: 100%; opacity: .5; }
.cover-inner { position: relative; max-width: 780px; margin: 0 auto; }
.cover .eyebrow { color: #C9A96E; }
.cover .badge { display: inline-block; border: 1px solid #E46BB0; color: #E46BB0; font-size: 11px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; padding: 4px 10px; margin: 28px 0 18px; }
html[dir="rtl"] .cover .badge { letter-spacing: 0; font-size: 13px; }
.cover .title { font-family: var(--serif); font-weight: 700; font-size: 48px; line-height: 1.05; margin: 0 0 16px; color: #F1EBE0; }
html[dir="rtl"] .cover .title { font-family: var(--ar-head); line-height: 1.35; }
.cover .rule { width: 100%; max-width: 420px; height: 2px; background: linear-gradient(90deg, #E46BB0, rgba(228,107,176,0) 80%); margin: 18px 0 18px; }
html[dir="rtl"] .cover .rule { background: linear-gradient(270deg, #E46BB0, rgba(228,107,176,0) 80%); }
.cover .subtitle { font-size: 17px; line-height: 1.6; color: #CFC7BA; max-width: 560px; margin: 0; }
.cover .parts { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 30px; }
.cover .parts span { border: 1px solid #3A332A; background: rgba(19,18,17,.75); padding: 5px 10px; font-size: 13px; color: #F1EBE0; }
.cover .parts b { color: #C9A96E; font-weight: 600; margin-inline-end: 6px; }
.cover .meta { margin-top: 34px; font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: #A39B8E; }
html[dir="rtl"] .cover .meta { letter-spacing: 0; font-size: 13px; }

/* ===== Panels ===== */
.panel { position: relative; background: var(--panel); border: 1px solid var(--border); padding: 18px 18px 8px; margin: 22px 0; }
.panel::before { content: ""; position: absolute; inset: -1px -1px auto -1px; height: 2px; background: linear-gradient(90deg, var(--mag), transparent 70%); }
html[dir="rtl"] .panel::before { background: linear-gradient(270deg, var(--mag), transparent 70%); }
.panel.gold::before { background: linear-gradient(90deg, var(--accent), transparent 70%); }
html[dir="rtl"] .panel.gold::before { background: linear-gradient(270deg, var(--accent), transparent 70%); }
.panel > h3, .panel > .ph { font-family: var(--serif); font-size: 22px; font-weight: 700; margin: 0 0 10px; }
html[dir="rtl"] .panel > :is(h3, .ph) { font-family: var(--ar-head); }

.titleblock { display: grid; grid-template-columns: 1fr 1fr; border: 1px solid var(--border); background: var(--panel); margin: 0 0 22px; }
.titleblock div { padding: 10px 14px; border-bottom: 1px solid var(--border); border-inline-end: 1px solid var(--border); }
.titleblock div:nth-child(2n) { border-inline-end: 0; }
.titleblock div:nth-last-child(-n+2) { border-bottom: 0; }
.titleblock .k { display: block; font-size: 10.5px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--muted); }
html[dir="rtl"] .titleblock .k { letter-spacing: 0; font-size: 12.5px; }
.titleblock .v { font-weight: 600; }

.chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 4px 0 12px; }
.chips a, .chips span { background: var(--sunk); border: 1px solid var(--border); padding: 6px 10px; font-size: 14px; color: var(--text); text-decoration: none; }
.chips b { color: var(--accent); margin-inline-end: 6px; font-weight: 600; }

/* ===== TOC ===== */
nav.toc ol { list-style: none; padding: 0; margin: 0; }
nav.toc li { margin: 0; }
nav.toc a { display: flex; gap: 10px; align-items: baseline; text-decoration: none; color: var(--text); padding: 6px 0; border-bottom: 1px solid var(--border); }
nav.toc a .t { flex: 1; }
nav.toc li.pt > a { font-family: var(--serif); font-weight: 700; font-size: 17px; padding-top: 12px; }
html[dir="rtl"] nav.toc li.pt > a { font-family: var(--ar-head); }
nav.toc li.pt > a .n { color: var(--mag); font-family: var(--sans); font-size: 12px; font-weight: 600; min-width: 48px; letter-spacing: .1em; text-transform: uppercase; }
html[dir="rtl"] nav.toc li.pt > a .n { font-family: var(--ar-body); letter-spacing: 0; font-size: 13px; min-width: 40px; }
nav.toc li.ls > a { padding-inline-start: 58px; font-size: 14.5px; color: var(--light); }
html[dir="rtl"] nav.toc li.ls > a { padding-inline-start: 50px; }
nav.toc .pg { display: none; font-variant-numeric: tabular-nums; color: var(--accent); }

/* ===== Callouts ===== */
.box { border: 1px solid var(--border); border-inline-start: 3px solid var(--text); background: var(--panel); padding: 14px 16px 4px; margin: 20px 0; }
.box .label { font-size: 11px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; margin-bottom: 6px; color: var(--text); }
html[dir="rtl"] .box .label { letter-spacing: 0; font-size: 13px; }
.box.tip { border-inline-start-color: var(--green); background: var(--green-t); }
.box.tip .label { color: var(--green); }
.box.warn { border-inline-start-color: var(--gold); background: var(--gold-t); }
.box.warn .label { color: var(--gold); }
.box.key { border-inline-start-color: var(--mag); background: var(--mag-t); }
.box.key .label { color: var(--mag); }
.box.note .label { color: var(--muted); }
.box.note { border-inline-start-color: var(--muted); }
.box p:last-child, .box ul:last-child, .box ol:last-child { margin-bottom: 10px; }

.case { background: var(--sunk); border: 1px solid var(--border); padding: 16px 18px 6px; margin: 22px 0; }
.case .label { font-size: 11px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--accent); }
html[dir="rtl"] .case .label { letter-spacing: 0; font-size: 13px; }
.case .case-title { font-family: var(--serif); font-size: 20px; font-weight: 700; margin: 4px 0 6px; }
html[dir="rtl"] .case .case-title { font-family: var(--ar-head); }
.case .fict { font-size: 12.5px; color: var(--muted); margin-bottom: 8px; font-style: italic; }
html[dir="rtl"] .case .fict { font-style: normal; }

.objectives { border: 1px solid var(--border); background: var(--panel); padding: 14px 16px 4px; margin: 14px 0 20px; }
.objectives .label { font-size: 11px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--mag); margin-bottom: 6px; }
html[dir="rtl"] .objectives .label { letter-spacing: 0; font-size: 13px; }

/* ===== Tables ===== */
.table-wrap { overflow-x: auto; -webkit-overflow-scrolling: touch; margin: 20px 0; border: 1px solid var(--border); background: var(--panel); }
table { border-collapse: collapse; width: 100%; font-size: 14.5px; line-height: 1.5; }
.table-wrap.wide table { min-width: 600px; }
.table-wrap.t2 table { table-layout: fixed; }
.table-wrap.t2 :is(td, th):first-child { width: 36%; }
caption { caption-side: top; text-align: start; font-family: var(--serif); font-weight: 700; font-size: 16px; padding: 10px 12px; border-bottom: 1px solid var(--border); }
html[dir="rtl"] caption { font-family: var(--ar-head); }
thead th { background: #0B0B0B; color: #F1EBE0; text-align: start; font-weight: 600; font-size: 11.5px; letter-spacing: .12em; text-transform: uppercase; padding: 10px 12px; vertical-align: bottom; }
html[dir="rtl"] thead th { letter-spacing: 0; font-size: 13.5px; }
:root[data-theme="dark"] thead th { background: #1C1A18; border-bottom: 1px solid #8A6A35; }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) thead th { background: #1C1A18; border-bottom: 1px solid #8A6A35; } }
td { padding: 10px 12px; vertical-align: top; border-top: 1px solid var(--border); text-align: start; overflow-wrap: anywhere; }
td.rowhead { font-weight: 600; }
td.blank { height: 34px; }

/* ===== Cycle ===== */
.cycle { border: 1px solid var(--border); background: var(--panel); padding: 16px 16px 12px; margin: 24px 0; position: relative; }
.cycle::before { content: ""; position: absolute; inset: -1px -1px auto -1px; height: 2px; background: linear-gradient(90deg, var(--accent), transparent 70%); }
html[dir="rtl"] .cycle::before { background: linear-gradient(270deg, var(--accent), transparent 70%); }
.cycle .cycle-title { font-family: var(--serif); font-weight: 700; font-size: 19px; margin-bottom: 2px; }
html[dir="rtl"] .cycle .cycle-title { font-family: var(--ar-head); }
.cycle .cycle-sub { color: var(--muted); font-size: 14px; margin-bottom: 14px; }
.cycle ol { list-style: none; padding: 0; margin: 0; counter-reset: step; }
.cycle li { counter-increment: step; position: relative; background: var(--bg); border: 1px solid var(--border2); padding: 9px 12px; padding-inline-start: 52px; margin: 0 0 24px; line-height: 1.45; }
.cycle li::before { content: counter(step); position: absolute; inset-inline-start: 0; top: 0; bottom: 0; width: 38px; background: var(--text); color: var(--bg); font-family: var(--serif); font-weight: 700; font-size: 17px; display: flex; align-items: center; justify-content: center; }
.cycle li::after { content: ""; position: absolute; left: 50%; bottom: -19px; width: 1px; height: 13px; background: var(--accent); }
.cycle li > .tri { position: absolute; left: calc(50% - 5px); bottom: -24px; border-left: 5px solid transparent; border-right: 5px solid transparent; border-top: 6px solid var(--accent); }
.cycle li:last-child { border-color: var(--mag); }
.cycle .loop { border: 1px dashed var(--mag); color: var(--mag); background: var(--mag-t); padding: 8px 12px; font-weight: 600; text-align: center; margin: 0; }

/* ===== Check yourself ===== */
.check { border: 1px solid var(--border); background: var(--panel); margin: 34px 0 10px; position: relative; }
.check::before { content: ""; position: absolute; inset: -1px -1px auto -1px; height: 2px; background: linear-gradient(90deg, var(--mag), transparent 70%); }
html[dir="rtl"] .check::before { background: linear-gradient(270deg, var(--mag), transparent 70%); }
.check .ch-head { padding: 14px 16px 4px; font-family: var(--serif); font-weight: 700; font-size: 19px; }
html[dir="rtl"] .check .ch-head { font-family: var(--ar-head); }
.check .lvl { padding: 6px 16px 4px; border-top: 1px solid var(--border); }
.check .lvl .lv { font-size: 11px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--accent); margin: 6px 0 4px; }
html[dir="rtl"] .check .lvl .lv { letter-spacing: 0; font-size: 13px; }
.check ol { margin-bottom: 8px; }

/* ===== Playbook ===== */
.pb-level { margin: 28px 0 8px; display: flex; align-items: baseline; gap: 12px; border-bottom: 1px solid var(--border2); padding-bottom: 8px; }
.pb-level .n { font-family: var(--serif); font-size: 34px; font-weight: 700; color: var(--accent); line-height: 1; }
.pb-level .t { font-family: var(--serif); font-size: 21px; font-weight: 700; }
html[dir="rtl"] .pb-level :is(.n, .t) { font-family: var(--ar-head); }
.pb-level .d { color: var(--muted); font-size: 14px; }
details.qa { border: 1px solid var(--border); background: var(--panel); margin: 8px 0; }
details.qa summary { cursor: pointer; padding: 11px 14px; font-weight: 600; list-style: none; display: flex; gap: 10px; }
details.qa summary::-webkit-details-marker { display: none; }
details.qa summary .q { color: var(--accent); min-width: 2.2em; font-variant-numeric: tabular-nums; }
details.qa summary::after { content: "+"; margin-inline-start: auto; color: var(--muted); font-weight: 400; }
details.qa[open] summary::after { content: "−"; }
details.qa .ans { padding: 0 14px 6px; padding-inline-start: 46px; border-top: 1px dashed var(--border); }
details.qa .ans .al { font-size: 10.5px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--green); margin: 10px 0 2px; }
html[dir="rtl"] details.qa .ans .al { letter-spacing: 0; font-size: 12.5px; }

.script { border: 1px solid var(--border); background: var(--panel); margin: 20px 0; }
.script .sh { padding: 12px 16px; border-bottom: 1px solid var(--border); display: flex; gap: 12px; align-items: baseline; }
.script .sh .sn { font-family: var(--serif); font-weight: 700; color: var(--mag); font-size: 22px; }
.script .sh .st { font-family: var(--serif); font-weight: 700; font-size: 19px; }
html[dir="rtl"] .script .sh :is(.sn, .st) { font-family: var(--ar-head); }
.script .sb { padding: 10px 16px 4px; }
.script .when { font-size: 14px; color: var(--muted); }
.script .say { border-inline-start: 3px solid var(--text); background: var(--sunk); padding: 12px 14px; margin: 10px 0 12px; font-size: 16.5px; line-height: 1.6; }
.script .say p:last-child { margin-bottom: 0; }
.script .say .who { font-size: 10.5px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--muted); display: block; margin-bottom: 2px; }
html[dir="rtl"] .script .say .who { letter-spacing: 0; font-size: 12.5px; }
.script .why { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 10px; }
.script .why > div { border: 1px solid var(--border); padding: 8px 12px 2px; font-size: 14.5px; }
.script .why .wl { font-size: 10.5px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; margin-bottom: 2px; }
html[dir="rtl"] .script .why .wl { letter-spacing: 0; font-size: 12.5px; }
.script .why .ok .wl { color: var(--green); }
.script .why .no .wl { color: var(--gold); }

.rp { border: 1px solid var(--border); background: var(--panel); padding: 14px 16px 6px; margin: 18px 0; }
.rp .cards { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 8px 0 10px; }
.rp .cards > div { background: var(--sunk); border: 1px solid var(--border); padding: 10px 12px 2px; font-size: 14.5px; }

.score td.pts { width: 110px; text-align: center; font-weight: 600; }
.score tfoot td { font-weight: 700; border-top: 2px solid var(--text); }

/* Notes & scratch */
.field { margin: 10px 0 16px; }
.field label { display: block; font-weight: 600; margin-bottom: 4px; }
.field .hint { font-size: 13.5px; color: var(--muted); margin-bottom: 6px; }
.field textarea, .field input, td textarea, td input {
  width: 100%; font: inherit; color: var(--text); background: var(--bg); border: 1px solid var(--border2);
  padding: 8px 10px; resize: vertical; border-radius: 0;
}
td textarea, td input { padding: 4px 6px; background: transparent; border: 0; border-bottom: 1px dashed var(--border2); min-height: 26px; }
.field textarea { min-height: 84px; }
.field textarea:focus, .field input:focus, td :is(textarea, input):focus { outline: 1px solid var(--accent); }
.lines { display: none; }
.saved { font-size: 12.5px; color: var(--green); }
.fill { border-bottom: 1px solid var(--border2); display: inline-block; min-width: 180px; }

/* Exam */
.quiz .q { border: 1px solid var(--border); background: var(--panel); padding: 12px 14px; margin: 0 0 12px; }
.quiz .q .stem { font-weight: 600; margin-bottom: 8px; }
.quiz .q ol.opts { list-style: none; padding: 0; margin: 0; }
.quiz .q ol.opts li { margin: 0 0 4px; }
.quiz .q label { display: flex; gap: 8px; align-items: flex-start; padding: 5px 8px; border: 1px solid transparent; cursor: pointer; }
.quiz .q label:hover { border-color: var(--border); background: var(--sunk); }
.quiz .q label b { color: var(--accent); min-width: 1.6em; }
.quiz .q input[type=radio] { margin-top: 6px; accent-color: #8A6A35; }
.quiz .q.right { border-color: var(--green); }
.quiz .q.wrong { border-color: var(--gold); }
.quiz .q .fb { display: none; margin-top: 8px; padding: 8px 10px; font-size: 14.5px; background: var(--sunk); border-inline-start: 3px solid var(--green); }
.quiz .q.wrong .fb { border-inline-start-color: var(--gold); }
.quiz .q.done .fb { display: block; }
.examctl { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin: 16px 0 26px; }
.btn { font: inherit; font-weight: 600; font-size: 13px; letter-spacing: .12em; text-transform: uppercase; padding: 10px 16px; border: 1px solid var(--text); background: var(--text); color: var(--bg); cursor: pointer; }
html[dir="rtl"] .btn { letter-spacing: 0; font-size: 14.5px; }
.btn.ghost { background: transparent; color: var(--text); }
.result { font-family: var(--serif); font-weight: 700; font-size: 20px; }
html[dir="rtl"] .result { font-family: var(--ar-head); }
.answers .a { border-inline-start: 3px solid var(--accent); background: var(--panel); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); border-inline-end: 1px solid var(--border); padding: 9px 12px; margin: 0 0 8px; font-size: 14.5px; }
.answers .a b { color: var(--accent); }

.summary { background: #0B0B0B; color: #F1EBE0; padding: 18px 20px 8px; margin: 24px 0; border: 1px solid #3A332A; position: relative; }
.summary::before { content: ""; position: absolute; inset: -1px -1px auto -1px; height: 2px; background: linear-gradient(90deg, #E46BB0, transparent 70%); }
html[dir="rtl"] .summary::before { background: linear-gradient(270deg, #E46BB0, transparent 70%); }
.summary .label { font-size: 11px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: #C9A96E; margin-bottom: 8px; }
html[dir="rtl"] .summary .label { letter-spacing: 0; font-size: 13px; }
.summary strong { color: #FFFFFF; }

.checklist { list-style: none; padding: 0; }
.checklist li { position: relative; padding-inline-start: 28px; }
.checklist li::before { content: ""; position: absolute; inset-inline-start: 0; top: .4em; width: 14px; height: 14px; border: 1.5px solid var(--text); }
.booklist li { margin-bottom: 10px; }
.booklist .bk { font-weight: 600; }
.bk-ar { display: block; font-weight: 600; text-align: right; }
html[dir="rtl"] .en, html[dir="rtl"] [dir="ltr"] { unicode-bidi: isolate; }
html[dir="rtl"] .en { direction: ltr; }
html[dir="rtl"] .en.nw { white-space: nowrap; }
.dir-ltr { direction: ltr; unicode-bidi: isolate; display: inline-block; }
.disclaimer { border: 1px solid var(--border); border-inline-start: 3px solid var(--gold); background: var(--panel); padding: 12px 16px; margin: 0 0 22px; font-size: 14.5px; }
.disclaimer b { color: var(--gold); }
.endmark { margin: 56px 0 0; padding-top: 14px; border-top: 1px solid var(--border2); text-align: center; font-size: 11px; font-weight: 600; letter-spacing: .2em; text-transform: uppercase; color: var(--muted); }
html[dir="rtl"] .endmark { letter-spacing: 0; font-size: 13px; }
.print-only { display: none; }

/* ===== Phone ===== */
@media (max-width: 560px) {
  body { font-size: 15.5px; }
  .cover { padding: 36px 16px 30px; }
  .cover .title { font-size: 36px; }
  .part-open h2 { font-size: 32px; }
  h3.lesson { font-size: 25px; }
  h4 { font-size: 19px; }
  .titleblock { grid-template-columns: 1fr; }
  .titleblock div { border-inline-end: 0 !important; border-bottom: 1px solid var(--border) !important; }
  .titleblock div:last-child { border-bottom: 0 !important; }
  .table-wrap.t2 table { font-size: 13.5px; }
  .table-wrap.t2 :is(td, th) { padding: 8px 9px; }
  .script .why, .rp .cards { grid-template-columns: 1fr; }
  details.qa .ans { padding-inline-start: 14px; }
  nav.toc li.ls > a { padding-inline-start: 22px; }
}

/* ===== Print / PDF (always light) ===== */
@media print {
  .appbar, .examctl, .no-print, .saved { display: none !important; }
  .print-only { display: block; }
  body { font-size: 10.4pt; line-height: 1.55; background: #FFFFFF; }
  html[dir="rtl"] body { font-size: 10.6pt; line-height: 1.75; }
  main { max-width: none; padding: 0; }
  .cover { page: cover; break-after: page; margin: 0; width: 210mm; height: 297mm; padding: 0; display: flex; }
  .cover-inner { padding: 30mm 20mm 22mm; max-width: none; margin: 0; width: 100%; display: flex; flex-direction: column; }
  .cover .title { font-size: 40pt; }
  .cover .meta { margin-top: auto; }
  .front { break-after: page; }
  nav.toc { break-after: page; }
  nav.toc .pg { display: inline; }
  nav.toc a { padding: 3px 0; }
  .part-open { break-before: page; margin-top: 0; }
  .part-open h2 { font-size: 30pt; }
  .part-open .thumb { width: 100%; }
  h3.lesson { break-before: page; margin-top: 0; font-size: 21pt; }
  h3.lesson.first { break-before: auto; margin-top: 18px; }
  h2, h3, h4, h5, .label, .case-title, .pb-level, caption { break-after: avoid; }
  h4 { font-size: 14pt; margin-top: 22px; }
  p { orphans: 3; widows: 3; }
  .box, .case, .cycle, .objectives, .summary, .quiz .q, .answers .a, .disclaimer, details.qa, .script, .rp .cards, .check .lvl, .field, .titleblock, .panel.keep { break-inside: avoid; }
  .script { break-inside: auto; }
  .script .sh, .script .say, .script .why { break-inside: avoid; }
  .table-wrap { overflow: visible; break-inside: auto; }
  .table-wrap table { min-width: 0 !important; }
  tr, td, th { break-inside: avoid; }
  thead { display: table-header-group; }
  details.qa summary::after { content: ""; }
  .field textarea { display: none; }
  .field .lines, td .lines { display: block; }
  .lines { height: var(--h, 64px); background-image: repeating-linear-gradient(to bottom, transparent 0 21px, var(--border2) 21px 22px); }
  td textarea, td input { display: none; }
  .quiz .q input[type=radio] { display: none; }
  .quiz .q label { padding: 2px 0; }
  a { text-decoration: none; }
  .cycle li { margin-bottom: 20px; padding-top: 6px; padding-bottom: 6px; }
  .cycle li::after { bottom: -16px; height: 11px; }
  .cycle li > .tri { bottom: -20px; }
}
.cover .fade { position: absolute; inset: 0; background: linear-gradient(90deg, rgba(11,11,11,.94) 0%, rgba(11,11,11,.85) 45%, rgba(11,11,11,.25) 85%); }
html[dir="rtl"] .cover .fade { background: linear-gradient(270deg, rgba(11,11,11,.94) 0%, rgba(11,11,11,.85) 45%, rgba(11,11,11,.25) 85%); }
html[dir="rtl"] .cover .topo { transform: scaleX(-1); }
@media print { .front nav.toc { break-before: page; } .front { break-after: page; } }

/* ===== Course player layout (on top of the content styles) ===== */
html, body { height: auto; }
body { min-height: 100vh; }
button { font: inherit; }
.appbar .crumb { cursor: pointer; }
.appbar .tbtn { width: auto; min-width: 34px; padding: 0 10px; font-family: var(--sans); font-weight: 600; font-size: 13px; letter-spacing: .06em; }
html[dir="rtl"] .appbar .tbtn { font-family: var(--ar-body); letter-spacing: 0; }
.appbar .tbtn.lang { font-family: var(--ar-body); font-size: 15px; letter-spacing: 0; }
html[dir="rtl"] .appbar .tbtn.lang { font-family: var(--sans); font-size: 13px; letter-spacing: .08em; }

#app { min-height: calc(100vh - 52px); }
.wrap { max-width: 1180px; margin: 0 auto; padding: 0 16px 80px; }
.page-head { padding: 28px 0 10px; }
.page-head h1 { font-size: 44px; margin: 0 0 6px; letter-spacing: -.01em; }
.crumbs { font-size: 11px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--muted); margin: 18px 0 4px; display: flex; gap: 8px; flex-wrap: wrap; }
html[dir="rtl"] .crumbs { letter-spacing: 0; font-size: 13px; }
.crumbs a { color: var(--accent); text-decoration: none; cursor: pointer; }
.crumbs span.sep { color: var(--border2); }

/* progress */
.prog { display: flex; align-items: center; gap: 10px; margin: 12px 0 4px; }
.prog .bar { flex: 1; height: 6px; background: var(--sunk); border: 1px solid var(--border); position: relative; overflow: hidden; }
.prog .bar i { position: absolute; inset: 0 auto 0 0; background: var(--accent); }
html[dir="rtl"] .prog .bar i { inset: 0 0 0 auto; }
.prog .pct { font-family: var(--serif); font-weight: 700; font-size: 18px; min-width: 52px; text-align: end; }
.prog .of { font-size: 13px; color: var(--muted); white-space: nowrap; }

/* home */
.hero { display: grid; grid-template-columns: 1.2fr 1fr; gap: 24px; align-items: end; padding: 26px 0 8px; border-bottom: 1px solid var(--border2); margin-bottom: 22px; }
.hero h1 { font-size: 46px; margin: 0 0 8px; }
.hero .resume { margin-top: 12px; }
.grid-mods { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 16px; }
.mcard { background: var(--panel); border: 1px solid var(--border); position: relative; cursor: pointer; display: flex; flex-direction: column; text-align: start; padding: 0; color: var(--text); }
.mcard::before { content: ""; position: absolute; inset: -1px -1px auto -1px; height: 2px; background: linear-gradient(90deg, var(--mag), transparent 70%); z-index: 2; }
html[dir="rtl"] .mcard::before { background: linear-gradient(270deg, var(--mag), transparent 70%); }
.mcard:hover { border-color: var(--border2); }
.mcard:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.mcard .body { padding: 12px 14px 14px; display: flex; flex-direction: column; gap: 4px; flex: 1; }
.mcard .mt { font-family: var(--serif); font-weight: 700; font-size: 21px; line-height: 1.2; }
html[dir="rtl"] .mcard .mt { font-family: var(--ar-head); line-height: 1.45; }
.mcard .meta { font-size: 13px; color: var(--muted); }
.mcard .prog { margin-top: auto; padding-top: 8px; }
.mcard.soon { cursor: default; opacity: .62; }
.mcard.soon .ph { aspect-ratio: 16/9; background: var(--sunk); border-bottom: 1px solid var(--border); display: grid; place-items: center; color: var(--muted); font-size: 12px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; }
html[dir="rtl"] .mcard.soon .ph { letter-spacing: 0; font-size: 13px; }
.sec-title { font-family: var(--serif); font-weight: 700; font-size: 24px; margin: 34px 0 12px; }
html[dir="rtl"] .sec-title { font-family: var(--ar-head); }

/* module / item layout */
.layout { display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: 28px; align-items: start; }
.side { position: sticky; top: 64px; max-height: calc(100vh - 76px); overflow: auto; background: var(--panel); border: 1px solid var(--border); margin-top: 18px; }
.side .sh { padding: 14px 14px 10px; border-bottom: 1px solid var(--border); }
.side .sh .mt { font-family: var(--serif); font-weight: 700; font-size: 18px; line-height: 1.25; cursor: pointer; }
html[dir="rtl"] .side .sh .mt { font-family: var(--ar-head); line-height: 1.5; }
.side .grp { font-size: 10.5px; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; color: var(--muted); padding: 12px 14px 4px; }
html[dir="rtl"] .side .grp { letter-spacing: 0; font-size: 12.5px; }
.side a.it { display: flex; gap: 10px; align-items: flex-start; padding: 8px 14px; color: var(--text); text-decoration: none; font-size: 14.5px; line-height: 1.35; border-inline-start: 2px solid transparent; cursor: pointer; }
.side a.it:hover { background: var(--sunk); }
.side a.it.cur { border-inline-start-color: var(--accent); background: var(--sunk); font-weight: 600; }
.side a.it .st { flex: none; width: 18px; height: 18px; border: 1.5px solid var(--border2); border-radius: 50%; margin-top: 1px; display: grid; place-items: center; }
.side a.it.done .st { background: var(--green); border-color: var(--green); }
.side a.it.done .st::after { content: ""; width: 8px; height: 4px; border-left: 2px solid var(--bg); border-bottom: 2px solid var(--bg); transform: rotate(-45deg) translate(1px, -1px); }
.side a.it .n { color: var(--accent); font-variant-numeric: tabular-nums; min-width: 26px; }
.side .back { display: block; padding: 10px 14px; border-top: 1px solid var(--border); font-size: 13px; color: var(--accent); cursor: pointer; text-decoration: none; }

.main { min-width: 0; }
.main .thumbwrap { margin: 18px 0 18px; border: 1px solid var(--border); }
.item-head .eyebrow { margin-top: 6px; }
.item-head h1 { font-size: 36px; margin: 0 0 12px; }
html[dir="rtl"] .item-head h1, html[dir="rtl"] .page-head h1, html[dir="rtl"] .hero h1 { line-height: 1.45; }
.content { max-width: 760px; }
.content > h4:first-child { margin-top: 10px; }

.itemnav { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; justify-content: space-between; border-top: 1px solid var(--border2); margin-top: 40px; padding-top: 16px; max-width: 760px; }
.itemnav .mid { display: flex; gap: 10px; align-items: center; }
.btn.done { background: var(--green); border-color: var(--green); color: #fff; }
.btn.sm { padding: 7px 12px; font-size: 12px; }
.btn[disabled] { opacity: .35; cursor: default; }
.mobile-toc { display: none; }
.note-ar { border: 1px dashed var(--gold); background: var(--gold-t); padding: 10px 14px; margin: 14px 0; font-size: 14.5px; }

/* drawer for phones */
.drawer-bg { position: fixed; inset: 0; background: rgba(0,0,0,.45); z-index: 40; display: none; }
.drawer-bg.open { display: block; }
@media (max-width: 900px) {
  .layout { grid-template-columns: 1fr; gap: 0; }
  .side { position: fixed; top: 0; bottom: 0; inset-inline-start: 0; width: min(86vw, 340px); max-height: none; margin: 0; z-index: 50; transform: translateX(-105%); transition: transform .2s ease; }
  html[dir="rtl"] .side { transform: translateX(105%); }
  .side.open { transform: none !important; }
  .mobile-toc { display: inline-flex; margin-top: 14px; }
  .hero { grid-template-columns: 1fr; }
  .hero h1, .page-head h1 { font-size: 34px; }
  .item-head h1 { font-size: 28px; }
}

/* ===== Thumbnails (spec: Psychology adaptation) ===== */
.th { container-type: inline-size; position: relative; width: 100%; aspect-ratio: 16 / 9; overflow: hidden; background-color: #0F1A2B;
  color: #F2F4F7; font-family: "Inter Display", "Barlow", sans-serif; }
.th .grid { position: absolute; inset: 0;
  background-image:
    linear-gradient(to right, #2A3D5C 1px, transparent 1px),
    linear-gradient(to bottom, #2A3D5C 1px, transparent 1px),
    linear-gradient(to right, #17253D 1px, transparent 1px),
    linear-gradient(to bottom, #17253D 1px, transparent 1px);
  background-size: 25cqw 25cqw, 25cqw 25cqw, 5cqw 5cqw, 5cqw 5cqw; }
.th .bar { position: absolute; top: 0; bottom: 0; left: 0; width: 1.72cqw; background: #F4A340; }
.th .shape { position: absolute; }
