.th .tag b { background: #F4A340; color: #0F1A2B; font-family: "IBM Plex Mono", monospace; font-weight: 700; font-size: 1.6cqw; letter-spacing: .08em; padding: .5cqw 1cqw; text-transform: uppercase; }
.th .tag span { font-family: "IBM Plex Mono", monospace; font-weight: 600; font-size: 1.5cqw; color: #7D8BA3; letter-spacing: .08em; text-transform: uppercase; }
.th .title { position: absolute; left: 5.6cqw; right: 26cqw; top: 13cqw; font-weight: 900; font-size: 7.4cqw; line-height: .98; text-transform: uppercase; letter-spacing: -.01em; color: #F2F4F7; }
.th .title.long { font-size: 6cqw; }
.th .sub { position: absolute; left: 5.6cqw; right: 30cqw; bottom: 5.2cqw; font-family: "Barlow", sans-serif; font-weight: 500; font-size: 1.9cqw; line-height: 1.35; color: #B7C1D1; }
.th .foot { position: absolute; left: 5.6cqw; bottom: 2.2cqw; font-family: "IBM Plex Mono", monospace; font-weight: 600; font-size: 1.15cqw; letter-spacing: .1em; color: #7D8BA3; text-transform: uppercase; }
.th .num { position: absolute; right: 5cqw; bottom: 7.4cqw; font-weight: 900; font-size: 13cqw; line-height: .85; color: #F4A340; text-align: right; letter-spacing: -.02em; }
.th .num.long { font-size: 9.5cqw; }
.th .lab { position: absolute; right: 5cqw; bottom: 4.4cqw; font-family: "IBM Plex Mono", monospace; font-weight: 600; font-size: 1.3cqw; letter-spacing: .1em; color: #B7C1D1; text-transform: uppercase; text-align: right; max-width: 30cqw; }
