/* ===== Scratch pad ===== */
.fab { position: fixed; bottom: 20px; inset-inline-end: 20px; z-index: 30; display: flex; align-items: center; gap: 8px; background: #0B0B0B; color: #F1EBE0; border: 1px solid #8A6A35; padding: 12px 16px; cursor: pointer; box-shadow: 0 6px 20px rgba(0,0,0,.25); font-weight: 600; font-size: 13px; letter-spacing: .1em; text-transform: uppercase; }
html[dir="rtl"] .fab { letter-spacing: 0; font-size: 14.5px; }
.fab svg { width: 18px; height: 18px; }
.fab .dot { width: 7px; height: 7px; border-radius: 50%; background: #E46BB0; display: none; }
.fab.has .dot { display: block; }

.pad { position: fixed; inset: 0; z-index: 60; background: rgba(11,11,11,.55); display: none; }
.pad.open { display: flex; justify-content: flex-end; }
html[dir="rtl"] .pad.open { justify-content: flex-start; }
.pad .sheet { width: min(760px, 100vw); height: 100%; background: var(--bg); border-inline-start: 1px solid var(--border2); display: flex; flex-direction: column; }
.pad .ph { display: flex; align-items: center; gap: 10px; padding: 10px 12px; background: #0B0B0B; color: #F1EBE0; border-bottom: 1px solid #8A6A35; }
.pad .ph .pt { font-family: var(--serif); font-weight: 700; font-size: 17px; flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
html[dir="rtl"] .pad .ph .pt { font-family: var(--ar-head); }
.pad .ph .saved { color: #7FC8A0; font-size: 12px; }
.pad .ph button { background: transparent; border: 1px solid #3A332A; color: #F1EBE0; height: 34px; min-width: 34px; cursor: pointer; display: grid; place-items: center; padding: 0 8px; }
.pad .tools { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; padding: 8px 10px; border-bottom: 1px solid var(--border); background: var(--panel); }
.pad .tools .g { display: flex; gap: 4px; align-items: center; padding-inline-end: 8px; border-inline-end: 1px solid var(--border); }
.pad .tools .g:last-child { border: 0; }
.pad .tb { width: 36px; height: 36px; display: grid; place-items: center; background: var(--bg); border: 1px solid var(--border); color: var(--text); cursor: pointer; padding: 0; }
.pad .tb svg { width: 18px; height: 18px; }
.pad .tb.on { border-color: var(--text); background: var(--sunk); box-shadow: inset 0 -2px 0 var(--accent); }
.pad .tb[disabled] { opacity: .35; cursor: default; }
.pad .sw { width: 26px; height: 26px; border-radius: 50%; border: 2px solid var(--border); cursor: pointer; padding: 0; }
.pad .sw.on { outline: 2px solid var(--text); outline-offset: 2px; }
.pad .sz { width: 30px; height: 30px; display: grid; place-items: center; background: transparent; border: 1px solid transparent; cursor: pointer; padding: 0; }
.pad .sz i { display: block; border-radius: 50%; background: var(--text); }
.pad .sz.on { border-color: var(--text); }
.pad .stage { flex: 1; min-height: 0; display: grid; place-items: center; padding: 12px; overflow: hidden; }
.pad .paper { position: relative; background: var(--panel); border: 1px solid var(--border2); box-shadow: 0 2px 14px rgba(0,0,0,.08); touch-action: none; }
.pad .paper canvas { position: absolute; inset: 0; width: 100%; height: 100%; touch-action: none; cursor: crosshair; }
.pad .paper.erasing canvas { cursor: cell; }
.pad .foot { display: flex; align-items: center; gap: 8px; padding: 8px 12px; border-top: 1px solid var(--border); background: var(--panel); font-size: 13px; }
.pad .foot .pg { font-variant-numeric: tabular-nums; min-width: 60px; text-align: center; }
.pad .foot .sp { flex: 1; }
.pad .confirm { display: none; align-items: center; gap: 8px; font-size: 13px; }
.pad .confirm.show { display: flex; }
.pad .hint { font-size: 12px; color: var(--muted); }
@media (max-width: 560px) {
  .pad .tools .g { padding-inline-end: 4px; }
  .pad .tb { width: 34px; height: 34px; }
  .fab .lbl { display: none; }
  .fab { padding: 14px; border-radius: 50%; }
}
.main .thumbwrap.sm { max-width: 520px; }
.fallback-en { direction: ltr; text-align: left; }
@media (max-width: 560px) { .pad .foot .hint { display: none; } .pad .foot .sp { display: block; } }

/* ===== parts & sections ===== */
.side .it.ov .n { color: var(--muted); }
.side .part { border-top: 1px solid var(--border); }
.side .part > .ph { width: 100%; display: grid; grid-template-columns: auto 1fr auto; gap: 2px 10px; align-items: baseline; padding: 10px 14px; background: transparent; border: 0; color: var(--text); cursor: pointer; text-align: start; }
.side .part > .ph .pn { grid-column: 1 / -1; font-size: 10.5px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--mag); }
html[dir="rtl"] .side .part > .ph .pn { letter-spacing: 0; font-size: 12.5px; }
.side .part > .ph .pt { grid-column: 1 / 3; font-weight: 600; font-size: 14.5px; line-height: 1.3; }
.side .part > .ph .pc { font-size: 12px; color: var(--muted); font-variant-numeric: tabular-nums; }
.side .part.pdone > .ph .pc { color: var(--green); font-weight: 600; }
.side .part .pis { display: none; padding-bottom: 6px; }
.side .part.open .pis { display: block; }
.side .part .pis a.it { padding-inline-start: 22px; font-size: 14px; }
.partstrip { display: flex; gap: 10px; align-items: baseline; border-bottom: 1px solid var(--border); padding: 10px 0 8px; margin: 14px 0 8px; color: var(--muted); font-size: 14px; }
.partstrip .eyebrow { margin: 0; color: var(--mag); }
.pcards { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 14px; margin-bottom: 30px; }
.pcard { background: var(--panel); border: 1px solid var(--border); padding: 0; text-align: start; color: var(--text); cursor: pointer; display: flex; flex-direction: column; }
.pcard:hover { border-color: var(--border2); }
.pcard .pbody { padding: 12px 14px; display: flex; flex-direction: column; gap: 4px; flex: 1; }
.pcard .eyebrow { margin: 0; }
.pcard .mt { font-family: var(--serif); font-weight: 700; font-size: 18px; line-height: 1.25; }
html[dir="rtl"] .pcard .mt { font-family: var(--ar-head); line-height: 1.5; }
.pcard .meta { font-size: 13.5px; color: var(--muted); line-height: 1.45; }
.pcard .secs { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 4px; }
.pcard .secs i { font-style: normal; font-size: 11.5px; padding: 2px 6px; border: 1px solid var(--border); color: var(--muted); font-variant-numeric: tabular-nums; }
.pcard .secs i.d { border-color: var(--green); color: var(--green); }
.pcard .prog { margin-top: auto; padding-top: 6px; }

/* ===== fabs & ink ===== */
.fabs { position: fixed; bottom: 20px; inset-inline-end: 20px; z-index: 30; display: flex; gap: 10px; }
.fabs .fab { position: static; }
.fab.ink.active { background: var(--mag); border-color: var(--mag); color: #fff; }
.inkhost { position: relative; }
.inklayer { position: absolute; top: 0; left: 0; pointer-events: none; z-index: 5; }
.inkhost.inking .inklayer { pointer-events: auto; touch-action: none; cursor: crosshair; }
.inkhost.inking { outline: 1px dashed var(--mag); outline-offset: 8px; }
.inkbar { position: fixed; left: 50%; transform: translateX(-50%); bottom: 84px; z-index: 40; display: none; flex-wrap: wrap; align-items: center; gap: 6px; padding: 8px 10px; background: var(--panel); border: 1px solid var(--border2); box-shadow: 0 8px 28px rgba(0,0,0,.18); max-width: calc(100vw - 24px); }
.inkbar.show { display: flex; }
.inkbar .tb { width: 34px; height: 34px; display: grid; place-items: center; background: var(--bg); border: 1px solid var(--border); color: var(--text); cursor: pointer; padding: 0; }
.inkbar .tb svg { width: 17px; height: 17px; }
.inkbar .tb.on { border-color: var(--text); box-shadow: inset 0 -2px 0 var(--mag); }
.inkbar .tb[disabled] { opacity: .35; }
.inkbar .sw { width: 24px; height: 24px; border-radius: 50%; border: 2px solid var(--border); cursor: pointer; padding: 0; }
.inkbar .sw.on { outline: 2px solid var(--text); outline-offset: 2px; }
.inkbar .sz { width: 28px; height: 28px; display: grid; place-items: center; background: transparent; border: 1px solid transparent; cursor: pointer; padding: 0; }
.inkbar .sz i { display: block; border-radius: 50%; background: var(--text); }
.inkbar .sz.on { border-color: var(--text); }
.inkbar .sep { width: 1px; height: 24px; background: var(--border); }
.inkbar .confirm { display: none; align-items: center; gap: 6px; font-size: 13px; }
.inkbar .confirm.show { display: flex; }
@media (max-width: 560px) { .inkbar { bottom: 80px; gap: 4px; padding: 6px; } .inkbar .sep { display: none; } .fabs { bottom: 16px; inset-inline-end: 14px; } }
@media print { .fabs, .inkbar { display: none !important; } }

html[dir="rtl"] td { overflow-wrap: break-word; }

/* review, mistakes, case tag, license */
.revbtns { display: inline-flex; flex-wrap: wrap; gap: 8px; margin-inline-start: 10px; vertical-align: middle; }
.hero .revbtns { margin: 10px 0 0; display: flex; }
.revbtns .cnt { display: inline-block; min-width: 20px; padding: 0 6px; margin-inline-start: 4px; background: var(--mag); color: #fff; border-radius: 10px; font-size: 11px; line-height: 18px; text-align: center; }
.revpage { max-width: 860px; }
.revbar { display: flex; flex-wrap: wrap; gap: 8px 12px; align-items: center; margin: 0 0 10px; }
.revbar .lbl { font-size: 11px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--muted); }
.revbar .chips { margin: 0; }
.chip { font: inherit; font-size: 13px; padding: 5px 11px; border: 1px solid var(--border2); background: var(--panel); color: var(--text); cursor: pointer; }
.chip.on { background: var(--text); color: var(--bg); border-color: var(--text); }
.revpage .content { margin-top: 18px; }
.quiz .q .src { font-size: 11.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); margin-bottom: 6px; }
.quiz .q .src .missn { color: var(--gold); }
.quiz .q .fb .srcl { font-size: 13px; color: var(--accent); cursor: pointer; text-decoration: underline; margin-inline-start: 6px; }
.qtag { display: inline-block; font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--mag); border: 1px solid var(--mag); padding: 1px 6px; margin-inline-end: 8px; vertical-align: 2px; }
.quiz .q.case { border-inline-start: 3px solid var(--mag); }
.revempty p { margin: 0; }
.license { font-size: 12.5px; color: var(--muted); border-top: 1px solid var(--border2); margin: 28px 0 10px; padding-top: 12px; max-width: 760px; }
@media (max-width: 720px) { .revbtns { margin: 10px 0 0; display: flex; } }

/* role-play lines and practice in threes */
.rp p.rplines { margin: 10px 0 4px; font-size: 13px; color: var(--mag); }
.rp ul.rplines { margin: 0; padding-inline-start: 18px; font-size: 14px; }
.rp ul.rplines li { margin: 0 0 4px; }
ol.trio-time { padding-inline-start: 22px; }
ol.trio-time li { margin: 0 0 4px; }
.trio-check td.cb { text-align: center; width: 52px; padding-inline: 4px; }
.trio-check th:not(:first-child) { width: 52px; padding-inline: 4px; text-align: center; }
.trio-check input[type=checkbox] { width: 18px; height: 18px; accent-color: var(--green); }

/* search, glossary, checked date */
.item-head .checked { font-size: 12.5px; color: var(--muted); margin: 6px 0 0; }
.findov { position: fixed; inset: 0; z-index: 60; background: rgba(0,0,0,.45); display: none; padding: 64px 16px 16px; }
.findov.open { display: block; }
.findbox { max-width: 760px; margin: 0 auto; background: var(--bg); border: 1px solid var(--border2); max-height: calc(100vh - 90px); display: flex; flex-direction: column; }
.findhead { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-bottom: 1px solid var(--border2); }
.findhead .icon { width: 20px; height: 20px; flex: none; color: var(--muted); }
.findhead input { flex: 1; min-width: 0; font: inherit; font-size: 16px; padding: 8px 4px; border: 0; background: transparent; color: var(--text); outline: none; }
.findres { overflow-y: auto; padding: 8px 12px 14px; }
.findres .glink { color: var(--accent); cursor: pointer; text-decoration: underline; }
.fgroup { margin: 6px 0 12px; }
.flbl { font-size: 11px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--mag); margin: 6px 0; }
.fhit { display: block; padding: 9px 10px; border: 1px solid var(--border); background: var(--panel); margin: 0 0 6px; cursor: pointer; color: var(--text); text-decoration: none; }
.fhit:hover { border-color: var(--accent); }
.fhit .src { display: block; font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); margin-bottom: 2px; }
.fhit .alt { color: var(--muted); font-size: 13px; margin-inline-start: 6px; }
.fhit .snip { display: block; font-size: 13.5px; color: var(--light); margin-top: 3px; }
.fhit mark, mark.hit { background: rgba(194,24,122,.18); color: inherit; padding: 0 2px; }
mark.hit { outline: 2px solid var(--mag); transition: outline-color 1s, background-color 1s; }
mark.hit.fade { outline-color: transparent; background: transparent; }
.gfilter { width: 100%; font: inherit; font-size: 16px; padding: 10px 12px; border: 1px solid var(--border2); background: var(--panel); color: var(--text); margin: 6px 0 16px; }
.glist { display: grid; gap: 8px; }
.gterm { border: 1px solid var(--border); background: var(--panel); padding: 10px 14px; }
.gterm .gt b { font-size: 16px; }
.gterm .gt { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 10px; }
.gterm .gt .alt { color: var(--muted); font-size: 14px; }
.gterm p { margin: 4px 0 6px; font-size: 14.5px; }
.gterm .gm { display: flex; flex-wrap: wrap; gap: 6px; }
.gterm .gm .chip { font-size: 11.5px; padding: 3px 8px; }
